import { ContentStore } from './src/store.js';
import { PolyglotExecutor } from './src/executor.js';
import { readFileSync, writeFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';

const fixture = '/tmp/context-mode-review-20261021/tests/fixtures/access.log';
const raw = readFileSync(fixture, 'utf8');
// String.raw preserves the regex and newline escapes for the executed code.
const code = String.raw`const lines = FILE_CONTENT.trim().split('\n'); const counts = {}; for (const line of lines) { const m = line.match(/" (\d{3}) /); if(m) counts[m[1]]=(counts[m[1]]||0)+1; } console.log(JSON.stringify({lines:lines.length,status:counts}));`;
const direct = execFileSync(process.execPath, ['-e', `const FILE_CONTENT=require('fs').readFileSync(${JSON.stringify(fixture)},'utf8');\n${code}`], {encoding:'utf8'});
const executor = new PolyglotExecutor();
const viaContext = await executor.executeFile({path: fixture, language:'javascript',code});
if (viaContext.exitCode !== 0 || direct !== viaContext.stdout) throw new Error('Native/context output mismatch');
const store = new ContentStore('/tmp/context-mode-review-20261021/review-chinese.db');
store.index({source:'synthetic-decisions',content:'# 决策记录\n只在取得明确授权之后才允许重启生产服务。\n\n# 网络故障\n家里的网络连接已经中断，需要排查线路。\n\n# Technical evidence\nECONNRESET occurred during websocket handshake.\n'});
const search = ['重启','明确授权','网络连接','断网','ECONNRESET','ZQXNONEXISTENTTOKEN'].map(query=>({query,results:store.searchWithFallback(query,3).map(r=>({title:r.title,content:r.content,layer:r.matchLayer}))}));
store.close();
const report = {nativeVsContext:{rawBytes:Buffer.byteLength(raw),nativeBytes:Buffer.byteLength(direct),contextBytes:Buffer.byteLength(viaContext.stdout),sameOutput:direct===viaContext.stdout,summary:JSON.parse(direct)},chineseSearch:search};
writeFileSync('/tmp/context-mode-review-20261021/review-probe-results.json',JSON.stringify(report,null,2));
console.log(JSON.stringify(report,null,2));

