import {Client} from '@modelcontextprotocol/sdk/client/index.js';
import {StdioClientTransport} from '@modelcontextprotocol/sdk/client/stdio.js';
import {writeFileSync} from 'node:fs';
const root='/tmp/context-mode-review-20261021';
const client=new Client({name:'Codex',version:'isolated-review'},{capabilities:{}});
const transport=new StdioClientTransport({command:process.execPath,args:['--import','tsx','src/server.ts'],cwd:root,stderr:'pipe',env:{PATH:process.env.PATH,HOME:process.env.HOME,CONTEXT_MODE_DATA_DIR:root+'/mcp-data',CONTEXT_MODE_PROJECT_DIR:root,CONTEXT_MODE_PLATFORM:'codex',CONTEXT_MODE_MCP_SENTINEL_DIR:root}});
let errors='';transport.stderr?.on('data',c=>errors+=c);
try {
 await client.connect(transport);
 const {tools}=await client.listTools();
 const listed=tools.map(t=>t.name);
 const exec=await client.callTool({name:'ctx_execute_file',arguments:{path:root+'/tests/fixtures/access.log',language:'javascript',code:'console.log(JSON.stringify({lineCount:FILE_CONTENT.trim().split("\\n").length}))'}});
 const idx=await client.callTool({name:'ctx_index',arguments:{content:'# Probe\nCM_REVIEW_7429 evidence survives indexing.',source:'review-probe'}});
 const positive=await client.callTool({name:'ctx_search',arguments:{queries:['CM_REVIEW_7429'],source:'review-probe'}});
 const negative=await client.callTool({name:'ctx_search',arguments:{queries:['ZQXNONEXISTENTTOKEN'],source:'review-probe'}});
 const report={tools:listed,toolSchemaBytes:Buffer.byteLength(JSON.stringify(tools)),exec,idx,positive,negative};
 if(exec.isError||idx.isError||positive.isError||!JSON.stringify(positive.content).includes('CM_REVIEW_7429')) throw new Error('MCP payload validation failed');
 writeFileSync(root+'/review-mcp-results.json',JSON.stringify(report,null,2));
 console.log(JSON.stringify(report,null,2));
} finally {await client.close(); if(errors)writeFileSync(root+'/review-mcp-stderr.log',errors);}
